describe('Footer Navigation Links', () => {
  beforeEach(() => {
    cy.visit('/');
  });

  it('should navigate to correct pages when clicking footer links', () => {
    // Verify footer is visible
    cy.get('[data-testid="footer"]').should('be.visible');

    // Verify footer links exist
    cy.get('[data-testid="footer-nav-link"]').should('have.length.greaterThan', 0);

    // Click 'About Us' link
    cy.get('[data-testid="footer-nav-link-about"]').click();

    // Verify navigation to About Us page
    cy.url().should('include', '/about');
    cy.get('[data-testid="page-title"]').should('contain', 'About Us');

    // Verify About Us page content is loaded
    cy.get('[data-testid="about-page-content"]').should('be.visible');

    // Click 'Contact' link
    cy.get('[data-testid="footer-nav-link-contact"]').click();

    // Verify navigation to Contact page
    cy.url().should('include', '/contact');
    cy.get('[data-testid="page-title"]').should('contain', 'Contact Us');

    // Verify Contact page content is loaded
    cy.get('[data-testid="contact-form"]').should('be.visible');

    // Click 'Privacy Policy' link
    cy.get('[data-testid="footer-nav-link-privacy"]').click();

    // Verify navigation to Privacy Policy page
    cy.url().should('include', '/privacy');
    cy.get('[data-testid="page-title"]').should('contain', 'Privacy Policy');

    // Verify Privacy Policy content is loaded
    cy.get('[data-testid="privacy-policy-text"]').should('be.visible');
  });

  it('should handle broken or non-existent footer links gracefully', () => {
    // Intercept API calls to simulate a broken link scenario
    cy.intercept('GET', '/api/broken-link').as('brokenLink');

    // Click a link that might be broken or point to a non-existent page
    cy.get('[data-testid="footer-nav-link-broken"]').click();

    // Verify navigation attempt
    cy.url().should('include', '/broken-link');

    // Verify error handling message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Page not found');

    // Verify user is not stuck in a loading state
    cy.get('[data-testid="page-content"]').should('be.visible');

    // Verify footer is still accessible
    cy.get('[data-testid="footer"]').should('be.visible');

    // Click a valid link to ensure navigation is still functional after error
    cy.get('[data-testid="footer-nav-link-about"]').click();

    // Verify navigation to About Us page
    cy.url().should('include', '/about');
    cy.get('[data-testid="page-title"]').should('contain', 'About Us');

    // Verify error message is no longer visible
    cy.get('[data-testid="error-message"]').should('not.exist');
  });
});
